export type MutationState = { id: number; origin: string; origins: Map<string, string>; deletes: Map<string, number>; restores: Map<string, string>; generation: string; deleted: boolean };
export function mutationKey(domain: "transaction" | "goal", action: "delete" | "restore", id: number, origin: string, from: string, to?: string, toOrigin?: string): string;
export function mutationInfo(metadata: Record<string, number> | undefined, domain: "transaction" | "goal"): Map<number, MutationState>;
export function mergeMutationMetadata(a?: Record<string, number>, b?: Record<string, number>): Record<string, number>;
export function rememberDeletion<T extends { id: number; restorationId?: string }>(metadata: Record<string, number>, domain: "transaction" | "goal", records: T[], originOf: (record: T) => string, now?: number): Record<string, number>;
export function rememberRestoration<T extends { id: number }>(metadata: Record<string, number>, domain: "transaction" | "goal", record: T, originOf: (record: T) => string, restorationId: string, now?: number): { record: T & { restorationId: string; restorationParent: string }; metadata: Record<string, number> };
export function rememberRebinding<T extends { id: number; restorationId?: string }>(metadata: Record<string, number>, domain: "transaction" | "goal", before: T, after: T, originOf: (record: T) => string, assertCreation: (before: T, after: T) => void, nonce: string, now?: number): { record: T & { restorationId: string; restorationParent: string }; metadata: Record<string, number> };
export function reconcileRecordCopies<T extends { id: number; restorationId?: string; restorationParent?: string }>(local: T[], remote: T[], localDeleted: number[], remoteDeleted: number[], localMeta: Record<string, number>, remoteMeta: Record<string, number>, domain: "transaction" | "goal", originOf: (record: T) => string, assertOrigin: (a: T, b: T) => void, mergeRecords: (a: T[], b: T[]) => T[]): { records: T[]; deletedIds: number[]; metadata: Record<string, number> };
export function metadataForRecord(metadata: Record<string, number>, domain: "transaction" | "goal", id: number): Record<string, number>;
export function metadataByRecord(metadata: Record<string, number>, domain: "transaction" | "goal"): Map<number, Record<string, number>>;
